// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @dev Principal-only internal accounting, NOT an authorized pool by itself.
/// Caller must verify exact deposit balance delta before credit, PQ-authorize
/// every debit, prevent reentrancy, and keep transfer failures atomic. Native
/// asset address(0) is supported; no share transfers or yield pricing here.
library QPoolLedger {
    struct Ledger {
        mapping(bytes32 => mapping(address => uint256)) balances;
        mapping(address => uint256) totalLiability;
    }

    error InvalidCredit();
    error InsufficientBalance();

    function credit(Ledger storage self, bytes32 account, address asset, uint256 amount) internal {
        if (account == bytes32(0) || amount == 0) revert InvalidCredit();
        self.balances[account][asset] += amount;
        self.totalLiability[asset] += amount;
    }

    function debit(Ledger storage self, bytes32 account, address asset, uint256 amount) internal {
        if (account == bytes32(0) || amount == 0) revert InsufficientBalance();
        if (self.balances[account][asset] < amount) revert InsufficientBalance();
        self.balances[account][asset] -= amount;
        self.totalLiability[asset] -= amount;
    }
}

