// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @dev Exact ERC20 deposits only. Caller must allowlist supported tokens,
/// prevent reentrancy, and credit principal only after successful pull.
/// Token balance reports are not protection against a malicious issuer.

library ExactPoolDeposit {
    error DepositFailed();

    function pull(address asset, address payer, uint256 amount) internal {
        // Reject invalid parameters
        if (asset.code.length == 0 || payer == address(0) || payer == address(this) || amount == 0) {
            revert DepositFailed();
        }

        // Read pre-transfer balances
        uint256 beforePool = balance(asset, address(this));
        uint256 beforePayer = balance(asset, payer);

        // Reject insufficient balance
        if (beforePayer < amount) {
            revert DepositFailed();
        }

        // Execute transferFrom
        (bool success, bytes memory data) = asset.call(
            abi.encodeWithSignature("transferFrom(address,address,uint256)", payer, address(this), amount)
        );

        // Validate transfer result
        if (!success || (data.length != 0 && data.length != 32) ||
            (data.length == 32 && abi.decode(data, (uint256)) != 1)) {
            revert DepositFailed();
        }

        // Read post-transfer balances
        uint256 afterPool = balance(asset, address(this));
        uint256 afterPayer = balance(asset, payer);

        // Validate balance changes
        if (afterPool < beforePool || afterPool - beforePool != amount || afterPayer != beforePayer - amount) {
            revert DepositFailed();
        }
    }

    function balance(address token, address account) private view returns (uint256) {
        (bool success, bytes memory data) = token.staticcall(
            abi.encodeWithSignature("balanceOf(address)", account)
        );
        if (!success || data.length != 32) {
            revert DepositFailed();
        }
        return abi.decode(data, (uint256));
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import "./QPoolLedger.sol";
import "./ExactPoolDeposit.sol";
import "../../qwallet/src/ExactAssetTransfer.sol";

/// @dev Abstract plumbing only, NOT an authorized pool. Concrete subclasses
/// MUST guard all state-changing entrypoints, validate registered accounts,
/// and require onchain PQ authorization for every principal release.
/// Supported tokens still require issuer/upgrade-policy review. No yield or shares.
abstract contract QPoolAssetCustody {
    using QPoolLedger for QPoolLedger.Ledger;

    QPoolLedger.Ledger private ledger;

    mapping(address => bool) public supported;

    bool private entered;

    error InvalidPoolAction();

    modifier guarded() {
        if (entered) revert InvalidPoolAction();
        entered = true;
        _;
        entered = false;
    }

    constructor(address[] memory tokens) {
        if (tokens.length > 16) revert InvalidPoolAction();
        for (uint256 i = 0; i < tokens.length; i++) {
            address token = tokens[i];
            if (token == address(0) || token == address(this) || token.code.length == 0) revert InvalidPoolAction();
            for (uint256 j = 0; j < i; j++) {
                if (tokens[j] == token) revert InvalidPoolAction();
            }
            supported[token] = true;
        }
    }

    function _account(bytes32 a) private pure returns (bytes32) {
        if (a == bytes32(0)) revert InvalidPoolAction();
        return a;
    }

    function _creditNative(bytes32 a, uint256 amount) internal {
        bytes32 acct = _account(a);
        if (amount == 0 || msg.value != amount) revert InvalidPoolAction();
        ledger.credit(acct, address(0), amount);
    }

    function _creditToken(bytes32 a, address asset, uint256 amount) internal {
        bytes32 acct = _account(a);
        if (amount == 0 || !supported[asset] || msg.value != 0) revert InvalidPoolAction();
        ExactPoolDeposit.pull(asset, msg.sender, amount);
        ledger.credit(acct, asset, amount);
    }

    function _release(bytes32 a, address asset, uint256 amount, address recipient) internal {
        bytes32 acct = _account(a);
        if (amount == 0 || (asset != address(0) && !supported[asset])) revert InvalidPoolAction();
        ledger.debit(acct, asset, amount);
        ExactAssetTransfer.send(asset, recipient, amount);
    }

    function balance(bytes32 a, address asset) external view returns (uint256) {
        return ledger.balances[a][asset];
    }

    function liability(address asset) external view returns (uint256) {
        return ledger.totalLiability[asset];
    }
}

