// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {QHooksSlhDsaProbe} from "../../slh-pq-benchmark/SlhDsaSha2128s.sol";
import {QPoolIntent} from "./QPoolIntent.sol";
import {QPoolWalletProof} from "./QPoolWalletProof.sol";

/// @dev Fixed-scheme local prototype. No fallback, key replacement, recovery or
/// upgrade route. Concrete state-changing entrypoints must use the custody guard.
abstract contract QPoolAuthorization {
    bytes32 private constant MODULE = bytes32("QHOOKS/QPOOL/SLH128S/V1");
    QHooksSlhDsaProbe public immutable verifier;
    bytes32 public immutable policyHash;

    struct Account { address owner; bytes32 publicKey; uint256 nextNonce; }
    mapping(bytes32 => Account) private accounts;

    error InvalidPoolConfiguration();
    error InvalidPoolAccount();
    error InvalidPoolIntent();
    error InvalidPoolWindow();
    error PoolPQAuthorizationFailed();

    event AccountEnrolled(bytes32 indexed accountId, address indexed owner, bytes32 publicKey);

    constructor(address verifier_, bytes32 policyHash_) {
        // No arbitrary success-returning verifier, delegatecall, mutable routing
        // or proxy is accepted. The shared verifier has no constructor state.
        if (verifier_.codehash != keccak256(type(QHooksSlhDsaProbe).runtimeCode)
            || policyHash_ == bytes32(0)) revert InvalidPoolConfiguration();
        verifier = QHooksSlhDsaProbe(verifier_);
        policyHash = policyHash_;
    }

    function accountIdFor(address owner, bytes32 publicKey) public view returns (bytes32) {
        return keccak256(abi.encode(block.chainid, address(this), owner, publicKey, policyHash));
    }

    function account(bytes32 id) external view returns (address owner, bytes32 publicKey, uint256 nextNonce) {
        Account storage a = accounts[id];
        return (a.owner, a.publicKey, a.nextNonce);
    }

    function _registered(bytes32 id) internal view returns (Account storage a) {
        a = accounts[id];
        if (id == bytes32(0) || a.owner == address(0)) revert InvalidPoolAccount();
    }

    function _enroll(address owner, bytes32 publicKey, uint64 validAfter, uint64 validUntil,
        bytes calldata walletSignature, bytes calldata pqSignature) internal returns (bytes32 id)
    {
        if (owner == address(0) || owner == address(this) || owner.code.length != 0
            || publicKey == bytes32(0)) revert InvalidPoolAccount();
        id = accountIdFor(owner, publicKey);
        if (id == bytes32(0) || accounts[id].owner != address(0)) revert InvalidPoolAccount();
        QPoolIntent.Action memory a = _action(1, id, owner, publicKey, 0, address(0), 0,
            owner, validAfter, validUntil);
        _verifyProofs(a, walletSignature, pqSignature);
        accounts[id] = Account(owner, publicKey, 1);
        emit AccountEnrolled(id, owner, publicKey);
    }

    function _consumeWithdrawal(bytes32 id, address asset, uint256 amount, address recipient,
        uint256 nonce, uint64 validAfter, uint64 validUntil,
        bytes calldata walletSignature, bytes calldata pqSignature) internal
    {
        Account storage account_ = _registered(id);
        if (amount == 0 || recipient == address(0) || recipient == address(this)
            || nonce != account_.nextNonce || nonce == type(uint256).max) revert InvalidPoolIntent();
        QPoolIntent.Action memory a = _action(2, id, account_.owner, account_.publicKey, nonce,
            asset, amount, recipient, validAfter, validUntil);
        _verifyProofs(a, walletSignature, pqSignature);
        // A failed asset payout reverts this update and the principal debit.
        account_.nextNonce = nonce + 1;
    }

    function _action(uint256 kind, bytes32 id, address owner, bytes32 publicKey, uint256 nonce,
        address asset, uint256 amount, address recipient, uint64 validAfter, uint64 validUntil)
        private view returns (QPoolIntent.Action memory)
    {
        if (validUntil <= validAfter || block.timestamp < validAfter || block.timestamp >= validUntil)
            revert InvalidPoolWindow();
        return QPoolIntent.Action({schemaVersion:1, chainId:block.chainid, pool:address(this),
            moduleId:MODULE, actionType:kind, accountId:id, owner:owner, publicKey:publicKey,
            policyHash:policyHash, nonce:nonce, asset:asset, amount:amount, recipient:recipient,
            validAfter:validAfter, validUntil:validUntil});
    }

    function _verifyProofs(QPoolIntent.Action memory a, bytes calldata walletSignature,
        bytes calldata pqSignature) private view
    {
        QPoolWalletProof.verify(a.owner, QPoolIntent.walletDigest(a), walletSignature);
        _verifyPQ(a, pqSignature);
    }

    function _verifyPQ(QPoolIntent.Action memory a, bytes calldata pqSignature) private view {
        if (pqSignature.length != 7856) revert PoolPQAuthorizationFailed();
        bool accepted;
        try verifier.verify(QPoolIntent.encode(a), pqSignature, abi.encodePacked(a.publicKey),
            QPoolIntent.context()) returns (bool result) { accepted = result; }
        catch { revert PoolPQAuthorizationFailed(); }
        if (!accepted) revert PoolPQAuthorizationFailed();
    }
}

