// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

library QPoolWalletProof {
    error PoolWalletAuthorizationFailed();

    uint256 private constant HALF_ORDER = 0x7fffffffffffffffffffffffffffffff5d576e7357a4501ddfe92f46681b20a0;

    function verify(
        address owner,
        bytes32 digest,
        bytes calldata signature
    ) internal pure {
        if (signature.length != 65 || owner == address(0)) revert PoolWalletAuthorizationFailed();

        bytes32 r;
        bytes32 s;
        uint8 v;

        assembly ("memory-safe") {
            r := calldataload(add(signature.offset, 0))
            s := calldataload(add(signature.offset, 32))
            v := byte(0, calldataload(add(signature.offset, 64)))
        }

        if (r == bytes32(0) || s == bytes32(0) || uint256(s) > HALF_ORDER || (v != 27 && v != 28)) revert PoolWalletAuthorizationFailed();

        address recovered = ecrecover(digest, v, r, s);
        if (recovered == address(0) || recovered != owner) revert PoolWalletAuthorizationFailed();
    }
}

