// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @dev Exact ERC20 deposits only. Caller must allowlist supported tokens,
/// prevent reentrancy, and credit principal only after successful pull.
/// Token balance reports are not protection against a malicious issuer.

library ExactPoolDeposit {
    error DepositFailed();

    function pull(address asset, address payer, uint256 amount) internal {
        // Reject invalid parameters
        if (asset.code.length == 0 || payer == address(0) || payer == address(this) || amount == 0) {
            revert DepositFailed();
        }

        // Read pre-transfer balances
        uint256 beforePool = balance(asset, address(this));
        uint256 beforePayer = balance(asset, payer);

        // Reject insufficient balance
        if (beforePayer < amount) {
            revert DepositFailed();
        }

        // Execute transferFrom
        (bool success, bytes memory data) = asset.call(
            abi.encodeWithSignature("transferFrom(address,address,uint256)", payer, address(this), amount)
        );

        // Validate transfer result
        if (!success || (data.length != 0 && data.length != 32) ||
            (data.length == 32 && abi.decode(data, (uint256)) != 1)) {
            revert DepositFailed();
        }

        // Read post-transfer balances
        uint256 afterPool = balance(asset, address(this));
        uint256 afterPayer = balance(asset, payer);

        // Validate balance changes
        if (afterPool < beforePool || afterPool - beforePool != amount || afterPayer != beforePayer - amount) {
            revert DepositFailed();
        }
    }

    function balance(address token, address account) private view returns (uint256) {
        (bool success, bytes memory data) = token.staticcall(
            abi.encodeWithSignature("balanceOf(address)", account)
        );
        if (!success || data.length != 32) {
            revert DepositFailed();
        }
        return abi.decode(data, (uint256));
    }
}

