// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

library QPoolIntent {
    struct Action {
        uint256 schemaVersion;
        uint256 chainId;
        address pool;
        bytes32 moduleId;
        uint256 actionType;
        bytes32 accountId;
        address owner;
        bytes32 publicKey;
        bytes32 policyHash;
        uint256 nonce;
        address asset;
        uint256 amount;
        address recipient;
        uint64 validAfter;
        uint64 validUntil;
    }

    function context() internal pure returns (bytes memory) {
        return bytes("QHOOKS/QPOOL/SLH128S/1");
    }

    function encode(Action memory a) internal pure returns (bytes memory) {
        return abi.encode(a);
    }

    function walletDigest(Action memory a) internal pure returns (bytes32) {
        bytes32 domain = keccak256(
            abi.encode(
                keccak256(
                    'EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)'
                ),
                keccak256('QHooks QPool'),
                keccak256('1'),
                a.chainId,
                a.pool
            )
        );
        bytes32 structHash = keccak256(
            abi.encodePacked(
                keccak256(
                    'QPoolAction(uint256 schemaVersion,uint256 chainId,address pool,bytes32 moduleId,uint256 actionType,bytes32 accountId,address owner,bytes32 publicKey,bytes32 policyHash,uint256 nonce,address asset,uint256 amount,address recipient,uint64 validAfter,uint64 validUntil)'
                ),
                encode(a)
            )
        );
        return keccak256(abi.encodePacked(hex"1901", domain, structHash));
    }
}

