// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {QPoolAssetCustody} from "./QPoolAssetCustody.sol";
import {QPoolAuthorization} from "./QPoolAuthorization.sol";

contract QPool is QPoolAssetCustody, QPoolAuthorization {
    constructor(address verifier_, address[] memory tokens)
        QPoolAssetCustody(tokens)
        QPoolAuthorization(verifier_, keccak256(abi.encode("QHOOKS/QPOOL/ASSETS/1", tokens)))
    {}

    event Deposited(bytes32 indexed accountId, address indexed asset, address indexed payer, uint256 amount);
    event Withdrawn(bytes32 indexed accountId, address indexed asset, address indexed recipient, uint256 amount, uint256 nonce);

    function enroll(
        address owner,
        bytes32 publicKey,
        uint64 validAfter,
        uint64 validUntil,
        bytes calldata walletSignature,
        bytes calldata pqSignature
    ) external guarded returns (bytes32) {
        return _enroll(owner, publicKey, validAfter, validUntil, walletSignature, pqSignature);
    }

    function depositNative(bytes32 id) external payable guarded {
        _registered(id);
        _creditNative(id, msg.value);
        emit Deposited(id, address(0), msg.sender, msg.value);
    }

    function depositToken(bytes32 id, address asset, uint256 amount) external guarded {
        _registered(id);
        _creditToken(id, asset, amount);
        emit Deposited(id, asset, msg.sender, amount);
    }

    function withdraw(
        bytes32 id,
        address asset,
        uint256 amount,
        address recipient,
        uint256 nonce,
        uint64 validAfter,
        uint64 validUntil,
        bytes calldata walletSignature,
        bytes calldata pqSignature
    ) external guarded {
        if (amount == 0 || (asset != address(0) && !supported[asset]) || amount > this.balance(id, asset)) {
            revert InvalidPoolAction();
        }
        _consumeWithdrawal(id, asset, amount, recipient, nonce, validAfter, validUntil, walletSignature, pqSignature);
        _release(id, asset, amount, recipient);
        emit Withdrawn(id, asset, recipient, amount, nonce);
    }
}

