// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

library ExactAssetTransfer {
    error TransferFailed();

    function send(address asset, address recipient, uint256 amount) internal {
        // Reject invalid parameters
        if (amount == 0 || recipient == address(0) || recipient == address(this)) {
            revert TransferFailed();
        }

        // Native asset transfer
        if (asset == address(0)) {
            uint256 before = address(this).balance;
            if (before < amount) revert TransferFailed();
            (bool success, ) = recipient.call{value: amount}("");
            if (!success || address(this).balance != before - amount) {
                revert TransferFailed();
            }
        } else {
            // ERC20 transfer
            if (asset.code.length == 0) {
                revert TransferFailed();
            }
            (bool success, bytes memory data) = asset.staticcall(abi.encodeWithSignature("balanceOf(address)", address(this)));
            if (!success || data.length != 32) {
                revert TransferFailed();
            }
            uint256 beforeSender = abi.decode(data, (uint256));
            (success, data) = asset.staticcall(abi.encodeWithSignature("balanceOf(address)", recipient));
            if (!success || data.length != 32) {
                revert TransferFailed();
            }
            uint256 beforeRecipient = abi.decode(data, (uint256));
            if (beforeSender < amount) {
                revert TransferFailed();
            }
            (success, data) = asset.call(abi.encodeWithSignature("transfer(address,uint256)", recipient, amount));
            if (!success || (data.length != 0 && data.length != 32) || (data.length == 32 && abi.decode(data, (uint256)) != 1)) {
                revert TransferFailed();
            }
            (success, data) = asset.staticcall(abi.encodeWithSignature("balanceOf(address)", address(this)));
            if (!success || data.length != 32) {
                revert TransferFailed();
            }
            uint256 afterSender = abi.decode(data, (uint256));
            (success, data) = asset.staticcall(abi.encodeWithSignature("balanceOf(address)", recipient));
            if (!success || data.length != 32) {
                revert TransferFailed();
            }
            uint256 afterRecipient = abi.decode(data, (uint256));
            if (afterSender != beforeSender - amount || afterRecipient < beforeRecipient || afterRecipient - beforeRecipient != amount) {
                revert TransferFailed();
            }
        }
    }
}
